-- =========================================================
-- CREACIÓN DE TABLA DEL BANCO DE PREGUNTAS DIAGNÓSTICAS (100 PREGUNTAS)
-- =========================================================

CREATE TABLE IF NOT EXISTS public.diagnostic_questions (
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    tenant_id UUID, 
    pillar VARCHAR(100) NOT NULL,
    code VARCHAR(50) UNIQUE,
    title TEXT NOT NULL,
    options JSONB NOT NULL,
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Limpiar tabla de base global
DELETE FROM public.diagnostic_questions WHERE tenant_id IS NULL;

